	/* @Override */
	public void addMappings(Collection<MapEntry<object,object>> entries, TaskMonitor monitor,
			bool truncateExisting, string description)
    {
		Map<Trace, List<MapEntry<object,object>>> byTrace =
			entries.stream().collect(Collectors.groupingBy(ent => ent.getFromTrace()));
		foreach (Map.Entry<Trace, List<MapEntry<object,object>>> ent in byTrace.entrySet()) {
			Trace trace = ent.getKey();
			using (Transaction tx = trace.openTransaction(description))
{
				doAddMappings(trace, ent.getValue(), monitor, truncateExisting);
			}
		}
	}

	protected static void doAddMappings(Trace trace, Collection<MapEntry<object,object>> entries,
			TaskMonitor monitor, bool truncateExisting)
    {
		foreach (MapEntry<object,object> ent in entries) {
			monitor.checkCancelled();
			try {
				DebuggerStaticMappingUtils.addMapping(ent, truncateExisting);
			}
			catch (Exception e) {
				Msg.error(typeof(DebuggerStaticMappingService),
					"Could not add mapping " + ent + ": " + e.getMessage());
			}
		}
	}

