	/* @Override */
	public void addModuleMappings(Collection<ModuleMapEntry> entries, TaskMonitor monitor,
			bool truncateExisting)
    {
		addMappings(entries, monitor, truncateExisting, "Add module mappings");

		Map<Program, List<ModuleMapEntry>> entriesByProgram = new();
		foreach (ModuleMapEntry entry in entries) {
			if (entry.isMemorize()) {
				entriesByProgram.computeIfAbsent(entry.getToProgram(), p => new())
						.add(entry);
			}
		}
		foreach (Map.Entry<Program, List<ModuleMapEntry>> ent in entriesByProgram.entrySet()) {
			using (Transaction tx = ent.getKey().openTransaction("Memorize module mapping"))
{
				foreach (ModuleMapEntry entry in ent.getValue()) {
					ProgramModuleIndexer.addModulePaths(entry.getToProgram(),
						List.of(entry.getModuleName()));
				}
			}
		}
	}

